#!/usr/bin/env bash
# tmpl-output-guard.sh — PreToolUse hook for Edit|Write|NotebookEdit calls.
# Denies an edit to a hydrated output: a file whose symlink-resolved path, or given path, or either of those with
# "." and ".." applied lexically, has a sibling <file>.tmpl is generated by hydrate.sh, so a direct edit is lost
# (gitignored output) or reverted (next hydrate). settings.json is exempt: the CLI writes it and hydrate.sh merges
# into it. Bash-path writes (sed -i, redirects) are out of this hook's reach. Hooks run in parallel; deny wins.

set -euo pipefail
source "$(dirname "$0")/_lib.sh"
hook_read_input

path=$(hook_field '.tool_input.file_path // .tool_input.notebook_path')
if [[ -z "$path" ]]; then
    exit 0
fi
# shellcheck disable=SC2088  # matching a literal, unexpanded ~/ as the tool payload carries it
if [[ "$path" == "~/"* ]]; then
    path="$HOME/${path#"~/"}"
elif [[ "$path" != /* ]]; then
    path="$(hook_field '.cwd')/$path"
fi

if hydrated_output_tmpl "$path"; then
    msg="HYDRATED OUTPUT: '$path' is generated from '$HYDRATED_TMPL' by hydrate.sh, so a direct edit is lost or"
    msg+=" reverted. Edit '$HYDRATED_TMPL' instead, then run that repo's hydrate.sh."
    hook_deny "$msg"
fi

exit 0
